insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_gov_v1'
from (values
('113.44.d.1.A',3,'Which idea from the Enlightenment holds that people are born with rights that government cannot take away?','["natural rights", "manifest destiny", "divine right", "mercantilism"]'::jsonb,0,'John Locke wrote about life, liberty and property.','original'),
('113.44.d.1.A',3,'The Declaration of Independence refers to ''the laws of Nature and of Nature''s God'' to argue what?','["that kings rule by law of heredity", "that rights come from a source higher than government", "that all taxes are fair", "that colonies must obey Parliament"]'::jsonb,1,'Natural law justified independence.','original'),
('113.44.d.1.B',3,'Which ancient society''s republic influenced the Framers'' idea of representative government?','["Persia", "Egypt", "Rome", "China"]'::jsonb,2,'Roman institutions included a senate and elected officials.','original'),
('113.44.d.1.B',3,'The Magna Carta influenced American government by establishing what idea?','["that nobles have no rights", "that kings are divine", "that taxes are never needed", "that even the ruler is bound by law"]'::jsonb,3,'It limited royal power in 1215.','original'),
('113.44.d.1.C',3,'Baron de Montesquieu is known for advocating what idea?','["separation of powers into branches", "the divine right of kings", "a state religion", "absolute monarchy"]'::jsonb,0,'His ideas shaped the U.S. Constitution.','original'),
('113.44.d.1.C',3,'John Locke''s writings most influenced which American document?','["the Articles of Confederation", "the Declaration of Independence", "the Northwest Ordinance", "the Mayflower Compact"]'::jsonb,1,'Jefferson echoed Locke''s natural rights.','original'),
('113.44.d.1.D',4,'James Madison is often called the ''Father of the Constitution'' mainly because he did what?','["led the Continental Army", "wrote the Declaration of Independence", "drafted the Virginia Plan and took detailed notes at the Convention", "served as the first president"]'::jsonb,2,'Madison shaped the framework and recorded debates.','original'),
('113.44.d.1.E',3,'The Great Compromise at the Constitutional Convention created what?','["a king as head of state", "a single-house legislature", "a weak national government", "a Senate with equal representation and a House based on population"]'::jsonb,3,'It resolved the large-state versus small-state dispute.','original'),
('113.44.d.1.E',3,'The Three-Fifths Compromise determined how enslaved people were counted for what?','["representation and taxation", "military draft", "citizenship", "voting rights"]'::jsonb,0,'It was a deeply unjust compromise between North and South.','original'),
('113.44.d.1.E',3,'Federalists and Anti-Federalists disagreed mainly over what?','["whether to have a flag", "how strong the national government should be", "which city should be the capital", "whether to fight England"]'::jsonb,1,'Anti-Federalists feared concentrated power and wanted a bill of rights.','original'),
('113.44.d.1.F',3,'Which individual is the author of the Declaration of Independence?','["George Washington", "John Adams", "Thomas Jefferson", "Alexander Hamilton"]'::jsonb,2,'Jefferson drafted it in 1776.','original'),
('113.44.d.1.F',3,'Alexander Hamilton, James Madison and John Jay wrote what?','["the Declaration of Independence", "the Articles of Confederation", "the Bill of Rights", "the Federalist Papers"]'::jsonb,3,'They urged ratification of the Constitution.','original'),
('113.44.d.2.A',3,'Which method do interest groups commonly use to influence government?','["lobbying lawmakers", "declaring war", "appointing judges", "printing money"]'::jsonb,0,'Lobbying presents information and pressure to officials.','original'),
('113.44.d.2.A',3,'Political parties try to gain power in government mainly by doing what?','["appointing judges directly", "nominating candidates and winning elections", "writing laws without voting", "ignoring voters"]'::jsonb,1,'Parties compete for votes.','original'),
('113.44.d.2.B',3,'Which movement used marches and protests to push for the Civil Rights Act of 1964?','["the temperance movement", "the labor movement", "the civil rights movement", "the Prohibition movement"]'::jsonb,2,'Citizen action led to legal change.','original'),
('113.44.d.3.A',3,'After each census, states with growing populations may do what?','["gain more senators", "lose Senate seats", "elect more presidents", "gain seats in the House of Representatives"]'::jsonb,3,'House seats are apportioned by population.','original'),
('113.44.d.3.A',3,'How often does the U.S. Census occur?','["every 10 years", "every 25 years", "every 2 years", "every 4 years"]'::jsonb,0,'The Constitution requires a census each decade.','original'),
('113.44.d.3.B',3,'Studying a map of congressional districts can help someone infer what?','["the price of gas", "how voters are distributed", "the age of the Constitution", "next year''s weather"]'::jsonb,1,'Maps reveal political patterns.','original'),
('113.44.d.3.C',3,'Drawing district lines to favor one party is called what?','["lobbying", "filibustering", "gerrymandering", "impeaching"]'::jsonb,2,'It can dilute voters'' influence.','original'),
('113.44.d.3.C',4,'Which Supreme Court principle requires districts to be roughly equal in population?','["separate but equal", "judicial review", "clear and present danger", "one person, one vote"]'::jsonb,3,'Cases such as Reynolds v. Sims established it.','original'),
('113.44.d.4.A',3,'Fiscal policy involves which government actions?','["taxing and spending", "choosing judges", "printing stamps", "declaring war"]'::jsonb,0,'Congress and the president set fiscal policy.','original'),
('113.44.d.4.A',3,'Monetary policy is mainly managed by which institution?','["the Department of Defense", "the Federal Reserve", "the Senate", "the Supreme Court"]'::jsonb,1,'The Fed controls the money supply and interest rates.','original'),
('113.44.d.4.B',3,'In the U.S. free enterprise system, the role of government is mainly to do what?','["set all prices", "own all businesses", "protect property rights and regulate unfair practices", "decide what each person makes"]'::jsonb,2,'Markets are mostly private.','original'),
('113.44.d.4.C',3,'Raising taxes on businesses can cause what economic effect?','["lower prices always", "higher profits for everyone", "no effect ever", "less money available for investment or hiring"]'::jsonb,3,'Taxes affect business decisions.','original'),
('113.44.d.4.C',3,'A regulation requiring factories to limit pollution is an example of what?','["government regulation of business", "a subsidy", "a tariff", "monetary policy"]'::jsonb,0,'Regulation protects public health.','original'),
('113.44.d.5.A',3,'Why does the U.S. pay close attention to oil-producing regions in its foreign policy?','["oil is not important", "energy resources are vital to the economy", "it has no oil", "oil is only used for art"]'::jsonb,1,'Resources shape national interests.','original'),
('113.44.d.5.B',3,'Who has the power to negotiate treaties?','["the Senate", "the Supreme Court", "the president", "the House of Representatives"]'::jsonb,2,'The president negotiates; the Senate approves.','original'),
('113.44.d.5.B',3,'How many Senators must approve a treaty for it to take effect?','["all of them", "three-fourths", "a simple majority", "two-thirds"]'::jsonb,3,'The Constitution requires a two-thirds vote.','original'),
('113.44.d.5.B',3,'Only Congress has the power to do what regarding war?','["declare war", "command the troops", "negotiate peace", "appoint ambassadors"]'::jsonb,0,'The president is commander in chief.','original'),
('113.44.d.6.A',3,'A written constitution is important because it does what?','["keeps rules secret", "sets clear rules and limits for government", "gives power to one ruler", "makes laws change daily"]'::jsonb,1,'It provides stability and accountability.','original'),
('113.44.d.6.B',3,'The Preamble states that one purpose of the Constitution is to ''establish justice.'' Which institution mainly serves that purpose?','["the army", "the cabinet", "the courts", "the post office"]'::jsonb,2,'Justice is administered by the judicial system.','original'),
('113.44.d.6.B',3,'The Preamble begins with the words ''We the People'' to show what?','["that kings rule", "that judges rule", "that states are above people", "that government gets its power from the people"]'::jsonb,3,'It expresses popular sovereignty.','original'),
('113.44.d.6.C',3,'Federalist No. 10 by James Madison warns about the dangers of what?','["factions", "state flags", "foreign trade", "standing armies"]'::jsonb,0,'A large republic can control factions.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_gov_v1'
from (values
('113.44.d.6.C',3,'Federalist No. 51 argues that ambition must counteract ambition through what?','["state control of all laws", "checks and balances among branches", "a single branch of power", "a powerful monarch"]'::jsonb,1,'It explains separation of powers.','original'),
('113.44.d.6.D',3,'Republicanism means that government power comes from what?','["wealth only", "inherited position", "elected representatives chosen by the people", "military rule"]'::jsonb,2,'Representatives act on behalf of citizens.','original'),
('113.44.d.6.D',3,'Which principle limits government by dividing power among branches and levels?','["unlimited power", "military rule", "absolute rule", "limited government"]'::jsonb,3,'The Constitution restrains government.','original'),
('113.44.d.6.E',3,'How many states must ratify a constitutional amendment for it to take effect?','["three-fourths", "two-thirds", "all of them", "one-half"]'::jsonb,0,'Amendment needs broad agreement.','original'),
('113.44.d.6.E',3,'A proposed amendment must first be passed by what?','["the president only", "two-thirds of both houses of Congress", "the Supreme Court", "a simple majority of the Senate"]'::jsonb,1,'Or by a convention called by two-thirds of the states.','original'),
('113.44.d.6.F',3,'The Declaration of Independence continues to shape American government by doing what?','["establishing a king", "creating the Senate", "affirming that governments exist to protect individual rights", "setting tax rates"]'::jsonb,2,'Its principles guide political debate.','original'),
('113.44.d.7.A',3,'The legislative branch of the U.S. government is called what?','["the Electoral College", "the Supreme Court", "the Cabinet", "Congress"]'::jsonb,3,'It makes federal laws.','original'),
('113.44.d.7.A',3,'Which chamber of Congress has 100 members?','["the Senate", "the Cabinet", "the Supreme Court", "the House of Representatives"]'::jsonb,0,'Each state has two senators.','original'),
('113.44.d.7.A',3,'Which chamber has the sole power to begin impeachment?','["the Supreme Court", "the House of Representatives", "the Cabinet", "the Senate"]'::jsonb,1,'The Senate holds the trial.','original'),
('113.44.d.7.A',3,'Revenue bills must begin in which chamber?','["the Senate", "the White House", "the House of Representatives", "the Supreme Court"]'::jsonb,2,'The House is closest to the people.','original'),
('113.44.d.7.B',3,'The president serves as head of state and what else?','["chief justice", "leader of the Senate", "Speaker of the House", "commander in chief of the armed forces"]'::jsonb,3,'The president directs the military.','original'),
('113.44.d.7.B',3,'A president can serve a maximum of how many elected terms?','["two", "one", "four", "three"]'::jsonb,0,'The 22nd Amendment set the limit.','original'),
('113.44.d.7.B',3,'Which official is president of the Senate and casts tie-breaking votes?','["the attorney general", "the vice president", "the chief justice", "the Speaker of the House"]'::jsonb,1,'The vice president votes only in ties.','original'),
('113.44.d.7.C',3,'The Supreme Court has how many justices?','["seven", "eleven", "nine", "twelve"]'::jsonb,2,'The number is set by law.','original'),
('113.44.d.7.C',3,'Judicial review, the power to declare laws unconstitutional, was established in which case?','["Plessy v. Ferguson", "Gideon v. Wainwright", "Brown v. Board of Education", "Marbury v. Madison"]'::jsonb,3,'Chief Justice Marshall wrote the 1803 decision.','original'),
('113.44.d.7.C',3,'Federal judges are appointed by the president and approved by whom?','["the Senate", "the Supreme Court", "the House", "the voters"]'::jsonb,0,'They serve during good behavior.','original'),
('113.44.d.7.D',3,'What is the main purpose of the National Aeronautics and Space Administration (NASA)?','["collecting taxes", "space exploration and research", "defending borders", "running elections"]'::jsonb,1,'It is an independent executive agency.','original'),
('113.44.d.7.D',3,'The Environmental Protection Agency (EPA) was created to do what?','["print money", "inspect airplanes", "enforce environmental laws", "supervise elections"]'::jsonb,2,'It protects air and water.','original'),
('113.44.d.7.D',3,'The Federal Reserve is mainly responsible for what?','["collecting taxes", "enforcing laws", "regulating the airlines", "regulating the money supply"]'::jsonb,3,'It sets monetary policy.','original'),
('113.44.d.7.E',3,'The president''s veto power is an example of what?','["a check on the legislative branch", "a check on the people", "a check on the courts", "a check on the states"]'::jsonb,0,'Congress can override with two-thirds.','original'),
('113.44.d.7.E',3,'How can Congress override a presidential veto?','["by a state vote", "by a two-thirds vote in both houses", "by a simple majority in one house", "by the Supreme Court''s approval"]'::jsonb,1,'It requires broad support.','original'),
('113.44.d.7.E',3,'The Senate''s power to confirm judges is an example of what?','["a check on the press", "a check on the states", "a check on the executive branch", "a check on voters"]'::jsonb,2,'Checks and balances limit each branch.','original'),
('113.44.d.7.F',4,'Judicial activism refers to judges doing what?','["always following precedent exactly", "never issuing opinions", "refusing to decide cases", "using their rulings to shape policy beyond a strict reading of law"]'::jsonb,3,'Restraint favors deference to legislatures.','original'),
('113.44.d.7.F',4,'Judicial restraint holds that courts should do what?','["defer to elected branches and precedent", "create new policy", "overturn most laws", "ignore the Constitution"]'::jsonb,0,'Restraint limits judicial power.','original'),
('113.44.d.7.G',3,'Which is a responsibility of the federal government?','["issuing driver''s licenses", "national defense", "running local schools", "paving city streets"]'::jsonb,1,'Defense and foreign policy are national.','original'),
('113.44.d.7.G',3,'Printing money and regulating interstate commerce are powers of whom?','["school boards", "city governments", "the federal government", "county governments"]'::jsonb,2,'These are delegated to Congress.','original'),
('113.44.d.7.H',3,'Which level of government typically runs public schools directly?','["Congress", "the Supreme Court", "the Department of Defense", "local school districts"]'::jsonb,3,'States set rules; districts operate schools.','original'),
('113.44.d.7.H',3,'Which official leads a state government?','["the governor", "the mayor", "the senator", "the president"]'::jsonb,0,'Governors are the chief executives of states.','original'),
('113.44.d.8.A',3,'Federalism is a system in which what happens?','["all power rests with states", "power is divided between national and state governments", "power is held by a monarch", "all power rests in the national government"]'::jsonb,1,'It was created to balance power.','original'),
('113.44.d.8.A',3,'The Articles of Confederation were replaced because they did what?','["were too long", "were written by Britain", "created a national government that was too weak", "created a king"]'::jsonb,2,'It could not tax or regulate trade.','original'),
('113.44.d.8.B',3,'Coining money is a power given to whom?','["counties only", "cities only", "states only", "the national government"]'::jsonb,3,'It is an exclusive federal power.','original'),
('113.44.d.8.B',3,'Which power is shared by national and state governments?','["taxing and building roads", "declaring war", "making treaties", "coining money"]'::jsonb,0,'Concurrent powers are held by both.','original'),
('113.44.d.8.B',3,'Establishing local governments and public schools is generally a power of whom?','["Congress", "the states", "the president", "foreign nations"]'::jsonb,1,'Reserved powers belong to the states.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
